const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-GB'),money=n=>'$'+Number(n).toFixed(4);let state,view='experiments',filter='all',query='',selected=new Set(),activeId,index=0,timer=null;
try{state=JSON.parse(localStorage.getItem('boukensha-lab-v1'))}catch{}if(!state?.runs){let control=Lab.simulate({orchestration:false,navigator:false,memory:'off',sessions:3,turns:24,seed:42});control.id='demo-control';let full=Lab.simulate({});full.id='demo-orchestrated';full.name='Navigator + persistent memory';let session=Lab.simulate({memory:'session',navigator:false,seed:42});session.id='demo-session';session.name='Checkpoint cadence · session memory';state={runs:[full,session,control],baseline:control.id,settings:{dashboard:'http://localhost:4568',jaeger:'http://localhost:16686'}}}activeId=state.runs[0]?.id;let compareIds=[state.baseline,state.runs[0]?.id];
function persist(){try{localStorage.setItem('boukensha-lab-v1',JSON.stringify(state));}catch{toast('Browser storage is full or unavailable. Export your runs to preserve changes.');}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function run(id=activeId){return state.runs.find(r=>r.id===id)||state.runs[0]};function baseline(){return state.runs.find(r=>r.id===state.baseline)}
const names={experiments:'Experiments',compare:'Compare runs',playback:'Run playback',memory:'Memory journal',observability:'Observability'};
function heading(k,title,sub,actions=''){return `<div class="title-row"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="actions">${actions}</div></div>`}
function stat(label,val,sub,icon='↗'){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${val}</div><div class="stat-sub">${sub}</div></div>`}
function options(id){return state.runs.map(r=>`<option value="${esc(r.id)}" ${id===r.id?'selected':''}>${esc(r.name)} · ${r.source==='simulation'?'SIM':'LOG'}</option>`).join('')}
function badge(r){return `<span class="pill ${r.source==='simulation'?'neutral':'green'}">${r.source==='simulation'?'Simulated':'Imported log'}</span>`}
function safeUrl(s){try{let u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function go(v){view=v;clearInterval(timer);timer=null;render()}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').innerHTML=`Workspace <b>/</b> ${names[view]}`;$('#main').innerHTML=({experiments:experiments,compare:comparison,playback:playback,memory:memory,observability:observability}[view])();bind()}
function experiments(){const all=state.runs,sim=all.filter(r=>r.source==='simulation').length;let rows=all.filter(r=>(filter==='all'||r.source===filter)&&r.name.toLowerCase().includes(query.toLowerCase()));return heading('EXPERIMENT WORKBENCH','A little structure. A lot to discover.','Explore what changes when your agent plans, navigates, and remembers.',`<button id="importBtn">↥ &nbsp; Import JSONL</button><button id="newBtn" class="primary">＋ New experiment</button>`)+`<div class="notice"><span>◇</span><span><strong>Start with a question.</strong> Demo runs are deterministic simulations. Import recorded logs to test your hypothesis against real evidence.</span></div><div class="stats">${stat('Experiments',fmt(all.length),`${sim} simulated · ${all.length-sim} imported`,'▦')}${stat('Comparison baseline',baseline()?.source==='imported'?'Recorded':'Week 2',baseline()?.source==='imported'?'Imported evidence selected':'Simulated control · no measured benchmark','⚑')}${stat('Memory lessons',fmt(all.reduce((n,r)=>n+r.lessons.length,0)),'Review evidence across session boundaries','◈')}${stat('Recorded runs',fmt(all.length-sim),'Import session or manager JSONL logs','⌁')}</div><section class="panel"><div class="panel-head"><div><h2>Experiment runs</h2><p class="muted">One hypothesis at a time. Keep conditions comparable.</p></div><button id="compareSelected" ${selected.size!==2?'disabled':''}>⇄ Compare ${selected.size?`(${selected.size})`:''}</button></div><div class="filters"><div class="tabs"><button data-filter="all" class="${filter==='all'?'active':''}">All runs</button><button data-filter="simulation" class="${filter==='simulation'?'active':''}">Simulations</button><button data-filter="imported" class="${filter==='imported'?'active':''}">Imported</button></div><input id="search" class="search" aria-label="Search experiments" placeholder="⌕  Search experiments" value="${esc(query)}"></div><div class="table-scroll"><table><thead><tr><th></th><th>Experiment / configuration</th><th>Source</th><th>Memory</th><th>Turns</th><th>Cost¹</th><th></th></tr></thead><tbody>${rows.map(r=>{let m=Lab.metrics(r);return `<tr><td><input class="selection" type="checkbox" data-select="${esc(r.id)}" aria-label="Select ${esc(r.name)}" ${selected.has(r.id)?'checked':''}></td><td><strong>${esc(r.name)} ${r.id===state.baseline?'<span class="pill">BASELINE</span>':''}</strong><small>${r.config.orchestration===true?'PLAN + CHECK':r.source==='imported'?'RECORDED LOG':'PLAYER ONLY'} · ${r.config.navigator?'NAV ON':'NAV OFF / UNKNOWN'} · SEED ${esc(r.config.seed??'—')}</small></td><td>${badge(r)}</td><td>${esc(r.config.memory||'Unknown')}</td><td>${fmt(m.turns)}</td><td>${m.costKnown?money(m.cost):'—'}</td><td><button class="row-open" data-open="${esc(r.id)}" aria-label="Open ${esc(r.name)}">↗</button></td></tr>`}).join('')}</tbody></table>${!rows.length?'<div class="empty">No matching runs. Import a log or create an experiment.</div>':''}</div><div class="panel-foot"><span>${rows.length} runs · ¹ Simulation costs are illustrative</span><button id="exportAll" class="linkbtn">Export workspace ↓</button></div></section><div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Follow the decision, not just the outcome</h2><p class="muted">Inspect what each role contributed along the way.</p></div><span class="pill">AGENT LOOP</span></div><div class="flow"><div class="phase">Plan<span>Planner</span></div><i>→</i><div class="phase">Play<span>Player + Navigator</span></div><i>→</i><div class="phase">Check<span>Judge</span></div><i>→</i><div class="phase">Remember<span>Chronicler</span></div></div></section><section class="panel"><div class="panel-head"><h2>Keep the baseline honest</h2><button class="linkbtn" data-go="compare">Compare runs ↗</button></div><div class="panel-body"><div class="baseline-info">Week 2 is the single Player with a persistent room map and observability. Demo control is illustrative; orchestration benefit is still unmeasured. Select an imported Week 2 run as your evidence baseline.</div></div></section></div>`}
function comparison(){let a=run(compareIds[0]),b=run(compareIds[1]);if(!a||!b)return heading('SIDE BY SIDE','Compare runs','Create or import two runs to begin.');const ma=Lab.metrics(a),mb=Lab.metrics(b);const fields=[['Turns','turns'],['Input tokens','input'],['Output tokens','output'],['Errors','errors'],['Replan verdicts','replans'],['Tool results / manager calls','tools']];return heading('SIDE BY SIDE','Find the difference that matters.','Match goal, seed, character, turn budget and starting state before interpreting a result.')+`<div class="notice">◇ ${a.source!==b.source?'Different sources: simulated and recorded results are not evidence of improvement.':a.source==='simulation'?'Illustrative comparison only. These results describe the simulation, not actual agent quality.':'Recorded evidence: confirm identical starting conditions and annotate outcomes before drawing conclusions.'}</div><div class="compare-grid">${[a,b].map((r,i)=>{let m=Lab.metrics(r);return `<section class="panel compare-card"><small>${i===0?'REFERENCE':'CANDIDATE'}</small><select aria-label="${i===0?'Reference':'Candidate'} run" data-compare="${i}">${options(r.id)}</select>${badge(r)}${fields.map(([label,key])=>`<div class="metric-row"><span>${label}</span><b>${fmt(m[key])}</b></div>`).join('')}<div class="metric-row"><span>Cost ${r.source==='simulation'?'(illustrative)':''}</span><b>${m.costKnown?money(m.cost):'Unknown / partial'}</b></div><div class="metric-row"><span>Outcome annotation</span><b>${esc(r.outcome)}</b></div><pre>${esc(JSON.stringify(r.config,null,2))}</pre><button data-baseline="${esc(r.id)}" ${r.id===state.baseline?'disabled':''}>${r.id===state.baseline?'Current baseline':'Set as comparison baseline'}</button></section>`}).join('')}</div><section class="panel"><div class="panel-head"><h2>Candidate − reference</h2><span class="pill neutral">DESCRIPTIVE ONLY</span></div><div class="panel-body">${fields.map(([label,key])=>`<div class="metric-row"><span>${label}</span><b>${mb[key]-ma[key]>0?'+':''}${fmt(mb[key]-ma[key])}</b></div>`).join('')}<p class="hint">Fewer errors or tokens do not establish better play. Record goal completion, use matched repeated seeds, and check memory provenance. The simulated seed controls randomness; branching can change later draws.</p></div></section>`}
function playback(){let r=run();if(!r)return '<div class="empty">Create a run to play it back.</div>';index=Math.min(index,r.events.length-1);let e=r.events[index],stage=Lab.stage(e);return heading('RUN PLAYBACK','Every decision leaves a trace.','Step through Plan, Play, Check and Remember. Raw events stay available for inspection.',`<button id="exportRun">Export JSONL ↓</button>`)+`<section class="panel"><div class="toolbar"><select id="activeRun" aria-label="Run to play back">${options(r.id)}</select>${badge(r)}<button id="playBtn">${timer?'Ⅱ Pause':'▷ Play'}</button><button id="prevBtn" ${index===0?'disabled':''} aria-label="Previous event">←</button><button id="nextBtn" ${index===r.events.length-1?'disabled':''} aria-label="Next event">→</button><select id="speed" aria-label="Playback speed"><option value="700">1× speed</option><option value="250">3× speed</option></select></div><div class="range"><small>${index+1} / ${r.events.length}</small><input type="range" id="scrub" aria-label="Event position" min="0" max="${r.events.length-1}" value="${index}"></div><div class="play-grid"><div class="timeline" id="timeline">${r.events.map((v,i)=>`<button data-event="${i}" class="${index===i?'active':''}"><span>${String(i+1).padStart(3,'0')} &nbsp; ${Lab.stage(v)}</span><span>${esc(v.phase||v.mode||'event')}</span></button>`).join('')}</div><div class="event-detail"><span class="pill">${stage}</span><span class="muted"> &nbsp; Turn ${esc(e.turn??'—')} · Session ${esc(e.session??'—')}</span><div class="event-text">${esc(e.text||e.result||e.detail||e.error||e.phase||e.mode||'Log event')}</div><p class="muted">${stage==='Navigate'?'Read-only assistance. Navigator cannot move the character.':stage==='Remember'?'Conditional memory write. Persistent lessons are available to future planning.':stage==='Check'?'Judge verdicts can continue, schedule replanning, or flag an issue.':'Only the Player performs game actions; the current implementation is human-driven.'}</p><details style="margin-top:24px"><summary class="muted">Inspect raw event</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details>${traceLink(e)}</div></div></section><section class="panel"><div class="panel-head"><h2>Research notes</h2><select id="outcome" style="width:170px" aria-label="Run outcome">${['unrated','goal achieved','goal not achieved','inconclusive'].map(v=>`<option ${r.outcome===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="panel-body"><label>Hypothesis, starting conditions, observations and limitations<textarea id="notes">${esc(r.notes)}</textarea></label><button id="saveNotes" style="margin-top:12px">Save notes</button></div></section>`}
function memory(){let r=run();return heading('PERSISTENT MEMORY','What carries into the next adventure?','Review lesson provenance and session boundaries. A digest informs the next plan, not every Player turn.')+`<section class="panel"><div class="toolbar"><select id="activeRun" aria-label="Memory run">${options(r?.id)}</select>${r?badge(r):''}<span class="muted">${esc(r?.config.memory||'Unknown memory mode')} · ${(r?.lessons||[]).length} captured lessons</span></div>${(r?.lessons||[]).map((l,i)=>`<article class="memory-card"><div class="memory-meta"><span class="pill">${esc(l.category)}</span><small>SESSION ${esc(l.session)} · TURN ${esc(l.turn)}</small></div><h3>${esc(l.text)}</h3><p>${r.config.memory==='session'?'Session-scoped. Not retained by the simulator into later sessions.':r.source==='simulation'?'Simulated lesson · retained locally for matching future simulations with persistent memory enabled.':'Imported memory event. Review the raw event for evidence.'}</p><button class="linkbtn" data-lesson="${i}">Review source event ↗</button></article>`).join('')||'<div class="empty">No explicit memory writes in this log. Chronicler response text is available in playback; lessons are never inferred from missing data.</div>'}</section><section class="panel"><div class="panel-head"><h2>Long-run review</h2><span class="pill neutral">HUMAN ASSESSMENT</span></div><div class="panel-body"><p class="muted">Look for repeated mistakes, stale advice, conflicting lessons and unresolved threads. The simulator retains explicit lesson history; it does not generate or evaluate a real Chronicler digest. Session-only memory ends at each boundary.</p><label>Memory assessment<textarea id="memoryNotes" placeholder="Which lessons survived? Were they useful, stale, or contradicted?">${esc(r?.memoryNotes||'')}</textarea></label><button id="saveMemory" style="margin-top:12px">Save assessment</button></div></section>`}
function traceLink(e){return /^[0-9a-f]{32}$/i.test(e.trace_id||'')?`<a target="_blank" rel="noopener" href="${esc(safeUrl(state.settings.jaeger).replace(/\/$/,'')+'/trace/'+e.trace_id)}">Open trace in Jaeger ↗</a>`:''}
function observability(){let r=run(),m=r?Lab.metrics(r):null;if(!r)return '<div class="empty">Import a log to inspect recorded telemetry.</div>';let groups={};r.events.filter(e=>e.phase==='response').forEach(e=>{let key=(e.task||'unknown')+' / '+(e.model||r.config.model||'unknown');let g=groups[key]||={calls:0,input:0,output:0,cost:0,known:true};g.calls++;g.input+=Number(e.input_tokens??e.usage?.input_tokens??0);g.output+=Number(e.output_tokens??e.usage?.output_tokens??0);g.cost+=Number(e.cost_usd||0);if(!Number.isFinite(e.cost_usd))g.known=false;});let timed=r.events.filter(e=>Number.isFinite(e.elapsed_ms)),errs=r.events.filter(e=>e.error||e.ok===false||e.event==='error'),traces=[...new Map(r.events.filter(e=>/^[0-9a-f]{32}$/i.test(e.trace_id||'')).map(e=>[e.trace_id,e])).values()];return heading('EVIDENCE INDEX','Your logs, in experiment context.','A focused index of imported evidence. Deep monitoring stays in the existing tools.',`<button id="importBtn">↥ Import JSONL</button>`)+`<section class="panel"><div class="toolbar"><select id="activeRun" aria-label="Observability run">${options(r.id)}</select>${badge(r)}<div class="obs-links"><a href="${esc(safeUrl(state.settings.dashboard))}" target="_blank" rel="noopener">Monitoring dashboard ↗</a><a href="${esc(safeUrl(state.settings.jaeger))}" target="_blank" rel="noopener">Jaeger ↗</a><button id="editLinks">Edit links</button></div></div></section><div class="stats">${stat('Response input',fmt(m.input),'Logged input tokens; cache counts separate')}${stat('Response output',fmt(m.output),'Logged output tokens')}${stat('Logged model cost',m.costKnown?money(m.cost):'Partial / unknown',`${m.priced} of ${m.responses} responses priced`)}${stat('Errors',fmt(m.errors),`${r.parseErrors?.length||0} malformed JSONL lines`,'!')}</div><section class="panel"><div class="panel-head"><h2>Model usage by role</h2><span class="pill neutral">${r.source==='simulation'?'ILLUSTRATIVE':'LOGGED VALUES'}</span></div><div class="table-scroll"><table><thead><tr><th>Role / model</th><th>Calls</th><th>Input</th><th>Output</th><th>Cost</th></tr></thead><tbody>${Object.entries(groups).map(([key,g])=>`<tr><td>${esc(key)}</td><td>${g.calls}</td><td>${fmt(g.input)}</td><td>${fmt(g.output)}</td><td>${g.known?money(g.cost):'Unknown / partial'}</td></tr>`).join('')}</tbody></table></div><div class="panel-foot">No current-price estimates. Unknown costs remain unknown; raw usage includes cache fields when logged.</div></section><div class="two-cols"><section class="panel"><div class="panel-head"><h2>Tool timing evidence</h2><span class="muted">${timed.length} timed calls</span></div><div class="table-scroll"><table><thead><tr><th>Tool</th><th>Elapsed</th><th>Error</th></tr></thead><tbody>${timed.slice(0,100).map(e=>`<tr><td>${esc(e.tool||e.name||e.mode||'unknown')}</td><td>${e.elapsed_ms} ms</td><td>${esc(e.error||'—')}</td></tr>`).join('')}</tbody></table></div>${!timed.length?'<div class="empty">No explicit elapsed_ms values. Import manager JSONL for timings; event-to-event deltas are not tool duration.</div>':''}</section><section class="panel"><div class="panel-head"><h2>Errors & traces</h2></div><div class="panel-body">${errs.slice(0,20).map(e=>`<p class="hint danger">Turn ${esc(e.turn)} · ${esc(e.error||e.detail||'Tool failed')}</p>`).join('')||'<p class="muted">No recorded errors.</p>'}<hr style="border:0;border-top:1px solid var(--line);margin:20px 0">${traces.map(e=>`<p>${traceLink(e)}</p>`).join('')||'<p class="muted">No trace IDs in this run. Simulation never fabricates Jaeger links.</p>'}${(r.parseErrors||[]).slice(0,15).map(e=>`<p class="hint danger">Line ${e.line}: ${esc(e.message)}</p>`).join('')}</div></section></div><p class="hint">Import each agent session or manager log as its own evidence run. Manager logs have no exact call correlation IDs; this view does not invent joins. Raw records remain accessible in playback and export.</p>`}
function download(name,text,type='application/json'){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{activeId=b.dataset.open;index=0;go('playback')});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});if($('#search'))$('#search').oninput=e=>{query=e.target.value;let start=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start)};
 document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(b.dataset.select):selected.delete(b.dataset.select);render()});if($('#compareSelected'))$('#compareSelected').onclick=()=>{compareIds=[...selected];go('compare')};if($('#newBtn'))$('#newBtn').onclick=()=>$('#runDialog').showModal();if($('#importBtn'))$('#importBtn').onclick=()=>$('#fileInput').click();if($('#exportAll'))$('#exportAll').onclick=()=>download('boukensha-workspace.json',JSON.stringify(state,null,2));if($('#exportRun'))$('#exportRun').onclick=()=>download(run().id+'.jsonl',run().events.map(e=>JSON.stringify(e)).join('\n'),'application/x-ndjson');document.querySelectorAll('[data-compare]').forEach(b=>b.onchange=()=>{compareIds[+b.dataset.compare]=b.value;render()});document.querySelectorAll('[data-baseline]').forEach(b=>b.onclick=()=>{state.baseline=b.dataset.baseline;persist();toast('Comparison baseline updated');render()});if($('#activeRun'))$('#activeRun').onchange=e=>{activeId=e.target.value;index=0;clearInterval(timer);timer=null;render()};document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{index=+b.dataset.event;render();$('#timeline .active')?.scrollIntoView({block:'nearest'})});if($('#scrub'))$('#scrub').oninput=e=>{index=+e.target.value;render()};if($('#prevBtn'))$('#prevBtn').onclick=()=>{index--;render()};if($('#nextBtn'))$('#nextBtn').onclick=()=>{index++;render()};if($('#playBtn'))$('#playBtn').onclick=()=>{if(timer){clearInterval(timer);timer=null;render()}else{if(index>=run().events.length-1)index=0;let speed=+$('#speed').value;timer=setInterval(()=>{if(index>=run().events.length-1){clearInterval(timer);timer=null}else index++;render()},speed);render()}};if($('#saveNotes'))$('#saveNotes').onclick=()=>{run().notes=$('#notes').value;run().outcome=$('#outcome').value;persist();toast('Research notes saved')};if($('#saveMemory'))$('#saveMemory').onclick=()=>{run().memoryNotes=$('#memoryNotes').value;persist();toast('Memory assessment saved')};document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{let l=run().lessons[+b.dataset.lesson];index=Math.max(0,run().events.findIndex(e=>(e.phase==='remember'||e.role==='chronicler'&&e.event==='written')&&e.turn===l.turn&&e.text===l.text));go('playback')});if($('#editLinks'))$('#editLinks').onclick=openSettings;
}
function openSettings(){let f=$('#settingsForm');f.elements.dashboard.value=state.settings.dashboard;f.elements.jaeger.value=state.settings.jaeger;$('#settingsDialog').showModal()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#settingsBtn').onclick=openSettings;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#settingsForm').onsubmit=e=>{e.preventDefault();let f=e.target;if([f.elements.dashboard.value,f.elements.jaeger.value].some(u=>safeUrl(u)==='#'))return toast('Use an http or https URL');state.settings={dashboard:f.elements.dashboard.value,jaeger:f.elements.jaeger.value};persist();$('#settingsDialog').close();render()};$('#runForm').onsubmit=e=>{e.preventDefault();let c=Object.fromEntries(new FormData(e.target));['orchestration','navigator','replan'].forEach(k=>c[k]=c[k]==='true');['checkpoint','turns','sessions','seed'].forEach(k=>c[k]=Number(c[k]));let prior=c.memory==='persistent'?state.runs.filter(r=>r.source==='simulation'&&r.config.character===c.character&&r.config.memory==='persistent').flatMap(r=>r.lessons):[];let r=Lab.simulate(c,prior);r.name=c.name;r.memoryPredecessors=c.memory==='persistent'?state.runs.filter(r=>r.source==='simulation'&&r.config.character===c.character&&r.config.memory==='persistent').map(r=>r.id):[];state.runs.unshift(r);activeId=r.id;persist();$('#runDialog').close();go('playback');toast('Simulation recorded. Explore the event playback.')};
$('#fileInput').onchange=async e=>{let added=0;for(let file of e.target.files){if(file.size>20000000){toast(file.name+': maximum file size is 20 MB');continue}try{let text=await file.text();if(file.name.endsWith('.json')){let imported=JSON.parse(text);if(Array.isArray(imported.runs)&&imported.settings){if(!imported.runs.every(r=>r.id&&Array.isArray(r.events)&&r.config&&Array.isArray(r.lessons)&&typeof r.name==='string'&&['simulation','imported'].includes(r.source)&&r.events.every(e=>e&&typeof e==='object'&&!Array.isArray(e))))throw Error('Invalid workspace structure');const ids=new Set(state.runs.map(r=>r.id));const fresh=imported.runs.filter(r=>!ids.has(r.id));state.runs.unshift(...fresh);added+=fresh.length;continue;}}let r=Lab.parseJSONL(text,file.name);state.runs.unshift(r);activeId=r.id;added++;}catch(err){toast(file.name+': '+err.message)}}persist();e.target.value='';render();if(added)toast(`${added} log(s) imported. JSONL stays in this browser.`)};
render();
